create or replace view public.registry_relationship_evidence_readiness_queue with (security_invoker = true) as select r.id as relationship_id,r.source_entity_type,r.source_entity_id,r.source_slug,r.target_entity_type,r.target_entity_id,r.target_slug,r.relationship_type,r.relationship_role,count(re.evidence_id)::integer as evidence_count,nullif(btrim(r.plain_reason),'') is not null as has_plain_reason,case when r.source_entity_id is null or r.target_entity_id is null then 'resolve_endpoints' when count(re.evidence_id)=0 then 'attach_evidence' when nullif(btrim(r.plain_reason),'') is null then 'add_plain_reason' else 'ready_for_review' end as evidence_work_state from public.registry_entity_relationships r left join public.registry_relationship_evidence re on re.relationship_id=r.id where r.relationship_status<>'archived' group by r.id;;
